    21	} from "@/components/ui/select";
    22	
    23	export type Role = "member" | "manager" | "owner";
    24	
    25	export const roleLabels: Record<Role, string> = {
    26	  member: "Member",
    27	  manager: "Manager",
    28	  owner: "Owner",
    29	};
    30	
    31	export type Plan = {
    32	  workspaceEmail: string;
    33	  saved: boolean;
    34	  unavailable: boolean;
    35	  groups: Array<{ id: string; email: string; name: string }>;
    36	  selected: Array<{ groupId: string; groupEmail: string; role: Role; manageable: boolean }>;
