    39	export function GroupMembershipPicker({
    40	  disabled,
    41	  errors,
    42	  plan,
    43	  roles,
    44	  setRoles,
    45	}: {
    46	  disabled?: boolean;
    47	  errors?: string;
    48	  plan: Plan;
    49	  roles: Record<string, Role>;
    50	  setRoles: React.Dispatch<React.SetStateAction<Record<string, Role>>>;
    51	}) {
    52	  const stale = plan.selected.filter((group) => !group.manageable && group.groupId in roles);
    53	
    54	  return (
    55	    <FieldSet data-invalid={Boolean(errors)}>
    56	      <FieldLegend>Group Assignment</FieldLegend>
    57	      <FieldGroup>
    58	        {plan.groups.length === 0 && stale.length === 0 && (
    59	          <p className="text-sm text-muted-foreground">No manageable groups are available.</p>
    60	        )}
    61	        {[
    62	          ...plan.groups.map((group) => ({ ...group, manageable: true })),
    63	          ...stale.map((group) => ({
    64	            id: group.groupId,
    65	            email: group.groupEmail,
    66	            name: group.groupEmail,
    67	            manageable: false,
    68	          })),
    69	        ].map((group) => (
    70	          <Field key={group.id} orientation="horizontal">
    71	            <Checkbox
    72	              checked={group.id in roles}
    73	              // A disabled role select must not dim its own checkbox while editing.
    74	              className={disabled ? undefined : "group-has-disabled/field:opacity-100"}
    75	              disabled={disabled}
    76	              id={`group-${group.id}`}
    77	              onCheckedChange={(checked) =>
    78	                setRoles((current) => {
    79	                  const { [group.id]: _removed, ...rest } = current;
    80	                  return checked ? { ...rest, [group.id]: "member" } : rest;
    81	                })
    82	              }
    83	            />
    84	            <FieldLabel htmlFor={`group-${group.id}`}>
    85	              <span className="flex flex-col">
    86	                {group.name}
    87	                <span className="font-normal text-muted-foreground">{group.email}</span>
    88	              </span>
    89	              {!group.manageable && <Badge variant="destructive">No longer manageable</Badge>}
    90	            </FieldLabel>
    91	            <Select
    92	              disabled={disabled || !(group.id in roles)}
    93	              items={roleLabels}
    94	              onValueChange={(role) =>
    95	                role && setRoles((current) => ({ ...current, [group.id]: role as Role }))
    96	              }
    97	              value={roles[group.id] ?? "member"}
    98	            >
    99	              <SelectTrigger aria-label={`Role in ${group.name}`} className="w-28">
   100	                <SelectValue />
   101	              </SelectTrigger>
   102	              <SelectContent>
   103	                <SelectGroup>
   104	                  {Object.entries(roleLabels).map(([value, label]) => (
   105	                    <SelectItem key={value} value={value}>
   106	                      {label}
   107	                    </SelectItem>
   108	                  ))}
   109	                </SelectGroup>
   110	              </SelectContent>
   111	            </Select>
   112	          </Field>
   113	        ))}
   114	        <FieldError>{errors}</FieldError>
   115	        {stale.length > 0 && (
   116	          <Alert variant="destructive">
   117	            <CircleAlertIcon />
   118	            <AlertTitle>A saved group needs revision</AlertTitle>
   119	            <AlertDescription>
   120	              Remove the group you can no longer manage before saving this plan.
   121	            </AlertDescription>
   122	          </Alert>
   123	        )}
   124	      </FieldGroup>
   125	    </FieldSet>
   126	  );
   127	}
