  1	import "server-only";
  2	
  3	import { randomBytes } from "node:crypto";
  4	
  5	import { z } from "zod";
  6	
  7	import { googleGet, googleSend, WorkspaceUnavailable } from "@/lib/workspace";
  8	
  9	export type ManageableGroup = { id: string; email: string; name: string };
 10	
 11	// The acting administrator whose OAuth grant makes every Directory call. There is no fallback
 12	// credential: a denied call is reported, never retried with anything stronger.
 13	export type Actor = { accessToken: string; profile: { id: string } };
 14	
 15	const directory = "https://admin.googleapis.com/admin/directory/v1";
 16	
 17	const assignmentsSchema = z.object({
 18	  items: z.array(z.object({ roleId: z.string() })).optional(),
 19	  nextPageToken: z.string().optional(),
 20	});
 21	const roleSchema = z.object({
 22	  isSuperAdminRole: z.boolean().optional(),
 23	  rolePrivileges: z.array(z.object({ privilegeName: z.string() })).optional(),
 24	});
 25	const createdUserSchema = z.object({ id: z.string().min(1) });
 26	const groupsSchema = z.object({
 27	  groups: z.array(z.object({ id: z.string(), email: z.string(), name: z.string() })).optional(),
 28	  nextPageToken: z.string().optional(),
 29	});
 30	
 31	async function* pages<T extends { nextPageToken?: string }>(
 32	  url: URL,
 33	  accessToken: string,
 34	  schema: z.ZodType<T>,
 35	) {
 36	  let pageToken: string | undefined;
 37	  do {
 38	    if (pageToken) url.searchParams.set("pageToken", pageToken);
 39	    const page = schema.parse(await googleGet(url, accessToken));
 40	    yield page;
 41	    pageToken = page.nextPageToken;
 42	  } while (pageToken);
 43	}
 44	
 45	// An address is taken by any user or group (aliases resolve to their owner).
 46	export async function isWorkspaceEmailAvailable(actor: Actor, email: string) {
 47	  const key = encodeURIComponent(email.toLowerCase());
 48	  for (const kind of ["users", "groups"]) {
 49	    if (await googleGet(`${directory}/${kind}/${key}?fields=id`, actor.accessToken, true))
 50	      return false;
 51	  }
 52	  return true;
 53	}
 54	
 55	// Google has no "can I write this group" probe, and group writes are gated by admin role
 56	// privileges across the customer, not per group. So the administrator either can write every
 57	// group (super admin, or a held role with GROUPS_ALL) or none.
 58	// ponytail: narrower Groups privileges (e.g. Groups Editor) count as "none"; widen if needed.
 59	async function canWriteGroups({ accessToken, profile }: Actor) {
 60	  const url = new URL(`${directory}/customer/my_customer/roleassignments`);
 61	  url.searchParams.set("userKey", profile.id);
 62	  url.searchParams.set("includeIndirectRoleAssignments", "true");
 63	  const roleIds = new Set<string>();
 64	  for await (const page of pages(url, accessToken, assignmentsSchema))
 65	    for (const item of page.items ?? []) roleIds.add(item.roleId);
 66	  for (const roleId of roleIds) {
 67	    const role = roleSchema.parse(
 68	      await googleGet(
 69	        `${directory}/customer/my_customer/roles/${encodeURIComponent(roleId)}`,
 70	        accessToken,
 71	      ),
 72	    );
 73	    if (role.isSuperAdminRole || role.rolePrivileges?.some((p) => p.privilegeName === "GROUPS_ALL"))
 74	      return true;
 75	  }
 76	  return false;
 77	}
 78	
 79	export async function listManageableGroups(actor: Actor): Promise<ManageableGroup[]> {
 80	  if (!(await canWriteGroups(actor))) return [];
 81	  const url = new URL(`${directory}/groups`);
 82	  url.searchParams.set("customer", "my_customer");
 83	  url.searchParams.set("maxResults", "200");
 84	  url.searchParams.set("fields", "nextPageToken,groups(id,email,name)");
 85	  const groups: ManageableGroup[] = [];
 86	  for await (const page of pages(url, actor.accessToken, groupsSchema))
 87	    groups.push(...(page.groups ?? []));
 88	  return groups.sort((a, b) => a.name.localeCompare(b.name));
 89	}
 90	
 91	// ponytail: group membership writes stay simulated until a later change; without GOOGLE_SIMULATION
 92	// they report the Workspace unavailable.
 93	function simulatedDomain() {
 94	  const domain = process.env.GOOGLE_WORKSPACE_DOMAIN;
 95	  if (process.env.GOOGLE_SIMULATION !== "true" || process.env.NODE_ENV === "production" || !domain)
 96	    throw new WorkspaceUnavailable();
 97	  return domain;
 98	}
 99	
100	// The create call may have reached Google even though no answer came back.
101	export class AccountCreateUncertain extends Error {
102	  constructor() {
103	    super("Account creation outcome unknown");
104	  }
105	}
106	
107	// `uncertain.user*` simulates a timeout after the request was sent.
108	export async function createWorkspaceUser(
109	  actor: Actor,
110	  { email, givenName, familyName }: { email: string; givenName: string; familyName: string },
111	): Promise<{ id: string }> {
112	  if (process.env.GOOGLE_SIMULATION === "true") {
113	    simulatedDomain();
114	    if (email.toLowerCase().startsWith("uncertain.user")) throw new AccountCreateUncertain();
115	    return { id: `sim-user-${email.toLowerCase()}` };
116	  }
117	  // The throwaway password is never stored or returned; the real first-login password is set
118	  // at handover.
119	  const created = createdUserSchema.parse(
