 91	// ponytail: group membership writes stay simulated until a later change; without GOOGLE_SIMULATION
 92	// they report the Workspace unavailable.
 93	function simulatedDomain() {
 94	  const domain = process.env.GOOGLE_WORKSPACE_DOMAIN;
 95	  if (process.env.GOOGLE_SIMULATION !== "true" || process.env.NODE_ENV === "production" || !domain)
 96	    throw new WorkspaceUnavailable();
 97	  return domain;
 98	}
