132	  const password = randomBytes(12).toString("base64url");
133	  if (process.env.GOOGLE_SIMULATION === "true") {
134	    simulatedDomain();
135	    return password;
136	  }
137	  await googleSend(
138	    `${directory}/users/${encodeURIComponent(userKey)}`,
139	    actor.accessToken,
140	    "PATCH",
141	    { password, changePasswordAtNextLogin: true },
142	  );
143	  return password;
144	}
