     1	import "server-only";
     2	
     3	import { and, eq, inArray, isNotNull, ne, notExists, sql } from "drizzle-orm";
     4	
     5	import {
     6	  addGroupMember,
     7	  createWorkspaceUser,
     8	  type Actor,
     9	  listManageableGroups,
    10	  type ManageableGroup,
    11	  resetWorkspacePassword,
    12	} from "@/lib/directory";
    13	import { getDb } from "@/lib/db";
    14	import { sendMailAsActor } from "@/lib/gmail";
    15	import { signupRequest, signupRequestGroup, signupRequestRevision } from "@/lib/schema";
    16	
    17	const provisioningStatuses = [
    18	  "accepted",
    19	  "provisioning",
    20	  "awaiting_handover",
    21	  "handover_confirmed",
    22	];
    23	
    24	// The decision is one conditional update, so repeated or concurrent accepts yield one winner.
    25	export async function acceptSignupRequest(id: string, approverDirectoryId: string) {
    26	  const [accepted] = await getDb()
    27	    .update(signupRequest)
    28	    .set({ status: "accepted", acceptedAt: new Date(), approvedByDirectoryId: approverDirectoryId })
    29	    .where(
    30	      and(
    31	        eq(signupRequest.id, id),
    32	        eq(signupRequest.status, "verified"),
    33	        isNotNull(signupRequest.workspaceEmail),
    34	      ),
    35	    )
    36	    .returning({ id: signupRequest.id });
    37	  return Boolean(accepted);
    38	}
    39	
    40	// Only the caller that moves accepted -> provisioning creates the account, and `attempting`
    41	// is persisted in that same statement, so an interrupted create is never silently repeated.
    42	// ponytail: runs inline in the accept request; an uncertain create waits for reconciliation (#11).
    43	export async function provisionAcceptedRequest(id: string, actor: Actor) {
    44	  const db = getDb();
    45	  const [claimed] = await db
    46	    .update(signupRequest)
    47	    .set({ status: "provisioning", accountCreateState: "attempting" })
    48	    .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "accepted")))
    49	    .returning({
    50	      workspaceEmail: signupRequest.workspaceEmail,
    51	      givenName: signupRequest.givenName,
    52	      familyName: signupRequest.familyName,
    53	    });
    54	  if (!claimed?.workspaceEmail) return;
    55	
    56	  let userId: string;
    57	  try {
    58	    userId = (
    59	      await createWorkspaceUser(actor, {
    60	        email: claimed.workspaceEmail,
    61	        givenName: claimed.givenName,
    62	        familyName: claimed.familyName,
    63	      })
    64	    ).id;
    65	  } catch {
    66	    // Any failure may have reached Google: keep it for reconciliation, do not repeat it.
    67	    await db
    68	      .update(signupRequest)
    69	      .set({ accountCreateState: "uncertain" })
    70	      .where(eq(signupRequest.id, id));
    71	    return;
    72	  }
    73	  await db
    74	    .update(signupRequest)
    75	    .set({ accountCreateState: "created", googleUserId: userId })
    76	    .where(eq(signupRequest.id, id));
    77	
    78	  await addUnfinishedMemberships(id, userId);
    79	  await completeIfAllAdded(id);
    80	  await sendHandoverBestEffort(id, actor);
    81	}
    82	
    83	// Touches only `pending` and `failed` groups, so successful memberships are never re-sent.
    84	// ponytail: overlapping retries can both try one unfinished group; the real Directory call (#11)
    85	// must treat "already a member" as success.
    86	async function addUnfinishedMemberships(id: string, userId: string) {
    87	  const db = getDb();
    88	  const groups = await db
    89	    .select()
    90	    .from(signupRequestGroup)
    91	    .where(
    92	      and(
    93	        eq(signupRequestGroup.signupRequestId, id),
    94	        inArray(signupRequestGroup.state, ["pending", "failed"]),
    95	      ),
    96	    );
    97	  for (const group of groups) {
    98	    let state = "added";
    99	    try {
   100	      await addGroupMember(group.groupId, userId, group.role);
   101	    } catch {
   102	      state = "failed";
   103	    }
   104	    await db
   105	      .update(signupRequestGroup)
   106	      .set({ state })
   107	      .where(
   108	        and(
   109	          eq(signupRequestGroup.signupRequestId, id),
   110	          eq(signupRequestGroup.groupId, group.groupId),
   111	        ),
   112	      );
   113	  }
   114	}
   115	
   116	// One conditional statement: handover is reached only when no selected membership is unfinished,
   117	// even if a revision or another retry runs at the same time.
   118	async function completeIfAllAdded(id: string) {
   119	  await getDb()
   120	    .update(signupRequest)
   121	    .set({ status: "awaiting_handover" })
   122	    .where(
   123	      and(
   124	        eq(signupRequest.id, id),
   125	        eq(signupRequest.status, "provisioning"),
   126	        eq(signupRequest.accountCreateState, "created"),
   127	        notExists(
   128	          getDb()
   129	            .select({ one: sql`1` })
   130	            .from(signupRequestGroup)
   131	            .where(
   132	              and(
   133	                eq(signupRequestGroup.signupRequestId, id),
   134	                ne(signupRequestGroup.state, "added"),
   135	              ),
   136	            ),
   137	        ),
   138	      ),
   139	    );
   140	}
   141	
   142	// Retries only unfinished memberships. An unknown account outcome is never repeated here.
   143	export async function retryProvisioning(
   144	  id: string,
   145	  actor: Actor,
   146	): Promise<"retried" | "uncertain" | "unavailable"> {
   147	  const [request] = await getDb()
   148	    .select({
   149	      status: signupRequest.status,
   150	      state: signupRequest.accountCreateState,
   151	      googleUserId: signupRequest.googleUserId,
   152	    })
   153	    .from(signupRequest)
   154	    .where(eq(signupRequest.id, id));
   155	  if (request?.status !== "provisioning") return "unavailable";
   156	  if (request.state !== "created" || !request.googleUserId) return "uncertain";
   157	  await addUnfinishedMemberships(id, request.googleUserId);
   158	  await completeIfAllAdded(id);
   159	  await sendHandoverBestEffort(id, actor);
   160	  return "retried";
   161	}
   162	
   163	export type AssignmentRevision = {
   164	  groupId: string;
   165	  replacement?: { groupId: string; groupEmail: string; role: "member" | "manager" | "owner" };
   166	};
   167	
   168	// Removes or replaces one unfinished assignment and records why. Successful memberships are
   169	// never touched. Returns false when the request or assignment is not revisable.
   170	export async function reviseAssignment(
   171	  id: string,
   172	  revision: AssignmentRevision,
   173	  adminDirectoryId: string,
   174	) {
   175	  return getDb().transaction(async (tx) => {
   176	    const [request] = await tx
   177	      .select({ status: signupRequest.status })
   178	      .from(signupRequest)
   179	      .where(eq(signupRequest.id, id))
   180	      .for("update");
   181	    if (request?.status !== "provisioning") return false;
   182	    const [removed] = await tx
   183	      .delete(signupRequestGroup)
   184	      .where(
   185	        and(
   186	          eq(signupRequestGroup.signupRequestId, id),
   187	          eq(signupRequestGroup.groupId, revision.groupId),
   188	          ne(signupRequestGroup.state, "added"),
   189	        ),
   190	      )
   191	      .returning();
   192	    if (!removed) return false;
   193	    const { replacement } = revision;
   194	    if (replacement)
   195	      await tx.insert(signupRequestGroup).values({ ...replacement, signupRequestId: id });
   196	    await tx.insert(signupRequestRevision).values({
   197	      signupRequestId: id,
   198	      removedGroupId: removed.groupId,
   199	      removedGroupEmail: removed.groupEmail,
   200	      replacementGroupId: replacement?.groupId,
   201	      replacementGroupEmail: replacement?.groupEmail,
   202	      replacementRole: replacement?.role,
   203	      revisedByDirectoryId: adminDirectoryId,
   204	    });
   205	    return true;
   206	  });
   207	}
