## Parent

#1

## What to build

Replace simulated Google account/group operations and captured message delivery with the real Google Workspace Directory API and dedicated Gmail sender grant. Preserve the existing durable recovery, notification, and account-handover behavior, and verify it in the configured tenant.

## Acceptance criteria

- [ ] Acceptance creates the Workspace user and all selected initial group memberships through the acting administrator permitted by Google, with existing recovery behavior preserved for partial and uncertain outcomes.
- [ ] The dedicated sender mailbox uses its separate Gmail grant to send verification, decision, and reviewer messages without exposing credentials or sending plaintext passwords.
- [ ] Google-denied operations, transport failures, and partial group results retain the established safe application state and retry actions.
- [ ] A live-tenant smoke check records real group roles, notification delivery, account handover, and behavior for suspended or deleted accounts with existing sessions.

## Blocked by

#7, #8, #9, #11
    assert.equal((await getProvisioningProgress(removeOnly, actor))?.status, "handover_confirmed");

    // An uncertain create is recorded and never repeated.
    const uncertain = await seed("uncertain.user", ["sim-events"]);
    await Promise.all([accept(uncertain), accept(uncertain)]);
    await accept(uncertain);
    progress = await getProvisioningProgress(uncertain, actor);
    assert.equal(progress?.status, "provisioning");
    assert.equal(progress?.accountCreateState, "uncertain");
    assert.equal(progress?.groups[0].state, "pending");
    assert.equal(await retryProvisioning(uncertain, actor), "uncertain");
    assert.equal((await getProvisioningProgress(uncertain, actor))?.groups[0].state, "pending");
    assert.equal(await retryProvisioning(ok, actor), "unavailable");

    // Without simulation the account is created through the Directory with the seeded names.
    const real = await seed("real", []);
    delete env.GOOGLE_SIMULATION;
    try {
      await accept(real);
    } finally {
      env.GOOGLE_SIMULATION = "true";
    }
    const [created] = await db.select().from(signupRequest).where(eq(signupRequest.id, real));
    assert.equal(created.googleUserId, `new-${created.workspaceEmail}`);
    assert.equal(created.accountCreateState, "created");
    assert.equal((await getProvisioningProgress(real, actor))?.status, "handover_confirmed");
    const insert = directory.writes.find(
      (write) => write.body.primaryEmail === created.workspaceEmail,
    );
    assert.deepEqual(insert?.body.name, { givenName: "Test", familyName: "Person" });
  } finally {
    directory.restore();
    for (const id of ids) await db.delete(signupRequest).where(eq(signupRequest.id, id));
    await db.$client.end();
  }
}

main().catch((error: unknown) => {
  console.error(error);
  process.exit(1);
});

